    const quickRows=()=>page.quickDiscovery.map((item,index)=>`<div class="quick-edit-row" data-quick-row="${esc(item.id)}"><label>Eyebrow<input data-quick="eyebrow" value="${esc(item.eyebrow)}"></label><label>Title<input data-quick="title" value="${esc(item.title)}"></label><label>Destination<input data-quick="route" value="${esc(item.route)}"></label><span><button type="button" data-quick-up="${index}" ${index===0?"disabled":""}>↑</button><button type="button" data-quick-down="${index}" ${index===page.quickDiscovery.length-1?"disabled":""}>↓</button><button type="button" data-quick-remove="${index}">Remove</button></span></div>`).join("");
    panel.innerHTML=`<form class="editor-form plain-form" data-homepage-form><div class="field-grid"><label class="wide">SEO title<input name="seoTitle" value="${esc(page.seo.title)}"></label><label class="wide">SEO description<textarea name="seoDescription">${esc(page.seo.description)}</textarea></label><label class="wide">Hero eyebrow<input name="heroEyebrow" value="${esc(page.hero.eyebrow)}"></label><label class="wide">Hero title<input name="heroTitle" value="${esc(page.hero.title)}"></label><label class="wide">Hero summary<textarea name="heroSummary">${esc(page.hero.summary)}</textarea></label></div><section class="homepage-curation"><h2>Quick Discovery</h2><p>Add, remove, edit and reorder the visitor pathways beneath the hero.</p><div class="quick-edit-list">${quickRows()}</div><button type="button" data-add-quick>Add Quick Discovery item</button></section>${picker("programmes","Homepage Programmes",data.programmes,page.experiences?.programmeIds,page.experiences?.featuredProgrammeId,page.experiences?.categoryLabels)}${picker("stories","Homepage Stories",data.stories,page.stories?.storyIds,page.stories?.featuredStoryId)}${picker("projects","Homepage Projects",data.projects,page.projects?.projectIds,page.projects?.featuredProjectId)}${picker("events","Homepage What’s On",data.events,page.current?.eventIds,page.current?.featuredEventId)}<section class="homepage-curation"><h2>Explore by Theme</h2><p>Theme links now come directly from Archive Categories. Choose visibility and order in Archive Categories; no duplicate theme list is stored here.</p><a class="button-link" href="#" data-open-categories>Manage Archive Categories</a></section><section class="homepage-curation"><h2>Homepage module order</h2><p>Move modules into the exact public-page order. Disabled modules are omitted.</p><div class="module-list" data-home-modules>${page.modules.map((module,index)=>`<div class="module-row" data-module="${module.id}"><input type="checkbox" ${module.enabled?"checked":""} aria-label="Show ${module.type}"><strong>${esc(module.type)}</strong><button type="button" data-up="${index}" ${index===0?"disabled":""}>Move up</button><button type="button" data-down="${index}" ${index===page.modules.length-1?"disabled":""}>Move down</button></div>`).join("")}</div></section><div class="form-actions"><button class="primary">Save homepage</button>${isProduction&&session?.role==="owner"?'<button type="button" data-publish-singleton="homepage">Build candidate</button>':""}<a class="button-link" href="/preview/" target="_blank">Preview homepage ↗</a>${!isProduction?'<button type="button" data-publish-homepage>Publish to Local Production</button>':""}</div></form>`;
    const form=panel.querySelector("form");
    const capture=()=>{page.seo.title=form.elements.seoTitle.value;page.seo.description=form.elements.seoDescription.value;page.hero.eyebrow=form.elements.heroEyebrow.value;page.hero.title=form.elements.heroTitle.value;page.hero.summary=form.elements.heroSummary.value;page.quickDiscovery=[...form.querySelectorAll("[data-quick-row]")].map((row,index)=>({id:row.dataset.quickRow||`quick-${Date.now()}-${index}`,eyebrow:row.querySelector('[data-quick="eyebrow"]').value,title:row.querySelector('[data-quick="title"]').value,route:row.querySelector('[data-quick="route"]').value}));const collectIds=key=>[...form.querySelectorAll(`[data-picker="${key}"] [data-pick-row]`)].filter(row=>row.querySelector('input[type="checkbox"]').checked).map(row=>row.dataset.pickRow);page.experiences.programmeIds=collectIds("programmes");page.experiences.featuredProgrammeId=form.querySelector('[data-featured-for="programmes"]').value;page.experiences.categoryLabels=Object.fromEntries([...form.querySelectorAll("[data-programme-label]")].map(input=>[input.dataset.programmeLabel,input.value]).filter(([,value])=>value));page.stories.storyIds=collectIds("stories");page.stories.featuredStoryId=form.querySelector('[data-featured-for="stories"]').value;page.projects.projectIds=collectIds("projects");page.projects.featuredProjectId=form.querySelector('[data-featured-for="projects"]').value;page.current ||= {};page.current.eventIds=collectIds("events");page.current.featuredEventId=form.querySelector('[data-featured-for="events"]').value;const moduleById=new Map(page.modules.map(module=>[module.id,module]));page.modules=[...form.querySelectorAll("[data-home-modules] [data-module]")].map(row=>({...moduleById.get(row.dataset.module),enabled:row.querySelector('input[type="checkbox"]').checked}));};
