    form.querySelectorAll("[data-pick-up]").forEach(button=>button.addEventListener("click",()=>moveRow(button,-1)));form.querySelectorAll("[data-pick-down]").forEach(button=>button.addEventListener("click",()=>moveRow(button,1)));
    form.querySelectorAll("[data-up]").forEach(button=>button.addEventListener("click",()=>moveRow(button,-1)));form.querySelectorAll("[data-down]").forEach(button=>button.addEventListener("click",()=>moveRow(button,1)));
    form.querySelectorAll("[data-quick-up]").forEach(button=>button.addEventListener("click",()=>{capture();const i=Number(button.dataset.quickUp);[page.quickDiscovery[i-1],page.quickDiscovery[i]]=[page.quickDiscovery[i],page.quickDiscovery[i-1]];data.homepage=page;homepageView();}));form.querySelectorAll("[data-quick-down]").forEach(button=>button.addEventListener("click",()=>{capture();const i=Number(button.dataset.quickDown);[page.quickDiscovery[i+1],page.quickDiscovery[i]]=[page.quickDiscovery[i],page.quickDiscovery[i+1]];data.homepage=page;homepageView();}));form.querySelectorAll("[data-quick-remove]").forEach(button=>button.addEventListener("click",()=>{capture();page.quickDiscovery.splice(Number(button.dataset.quickRemove),1);data.homepage=page;homepageView();}));form.querySelector("[data-add-quick]").addEventListener("click",()=>{capture();page.quickDiscovery.push({id:`quick-${Date.now()}`,eyebrow:"Explore",title:"New pathway",route:"/archives"});data.homepage=page;homepageView();});
